const BCE_LABELS = {
  ar: "ق.م.",
  zh: "公元前",
  nl: "v.Chr.",
  en: "BC",
  fr: "av. J.-C.",
  de: "v. Chr.",
  hu: "Kr. e.",
  it: "a.C.",
  ja: "紀元前",
  pl: "p.n.e.",
  pt: "a.C.",
  ru: "до н. э.",
  es: "a. C.",
};

function interpolate(template, params = {}) {
  return template.replace(/\{(\w+)\}/g, (match, key) =>
    params[key] === undefined || params[key] === null ? match : `${params[key]}`
  );
}

export function getExploreTranslations(locale = DEFAULT_LOCALE) {
  const normalizedLocale = SUPPORTED_LOCALES.includes(locale)
    ? locale
    : DEFAULT_LOCALE;
  const localeMessages = messages[normalizedLocale] || messages[DEFAULT_LOCALE];

  return (key, params) => interpolate(
    localeMessages[key] ?? messages[DEFAULT_LOCALE][key] ?? key,
    params,
  );
}

export function getExploreMessageKeys() {
  return Object.keys(messages[DEFAULT_LOCALE]);
}

export function getExploreLocaleMessages(locale) {
  return messages[locale] || null;
}

export function formatExploreNumber(value, locale = DEFAULT_LOCALE, options) {
  return new Intl.NumberFormat(locale, options).format(value);
}

export function formatExploreYear(value, locale = DEFAULT_LOCALE) {
  const rounded = Math.round(Number(value));
  if (!Number.isFinite(rounded)) return "";
  const number = formatExploreNumber(Math.abs(rounded), locale, {
    useGrouping: false,
  });
  if (rounded >= 0) return number;
  const era = BCE_LABELS[locale] || BCE_LABELS[DEFAULT_LOCALE];
  return locale === "zh" || locale === "ja"
    ? `${era}${number}`
    : `${number} ${era}`;
}
